pub fn binary_search(arr: &[i32], target: i32) -> Option<usize> {
    let (mut lo, mut hi) = (0usize, arr.len());
    while lo < hi {
        let mid = lo + (hi - lo) / 2;
        if arr[mid] == target { return Some(mid); }
        else if arr[mid] < target { lo = mid + 1; }
        else { hi = mid; }
    }
    None
}

fn main() {
    println!("{:?}", binary_search(&[1, 3, 5, 7, 9], 5));
}
